import json
# Get Souvlaki from grammar_only output
with open('outputs/docred_grammar_only.jsonl') as f:
    for line in f:
        rec = json.loads(line)
        doc_id = rec.get('doc_id', rec.get('title', ''))
        if 'Souvlaki' in doc_id or 'souvlaki' in doc_id.lower():
            # Print all triples/relations
            output = rec.get('output', rec.get('prediction', ''))
            if isinstance(output, str):
                try:
                    parsed = json.loads(output)
                except:
                    parsed = output
            else:
                parsed = output

            if isinstance(parsed, dict):
                relations = parsed.get('relations', parsed.get('triples', []))
            elif isinstance(parsed, list):
                relations = parsed
            else:
                relations = []

            print(f'Doc: {doc_id}, relations count: {len(relations)}')
            for r in relations:
                rel_name = r.get('relation', r.get('type', ''))
                print(f'  {r.get(\"head\",\"?\")} -> [{rel_name}] -> {r.get(\"tail\",\"?\")}')
            break
"

